#[path="../native-pencil-tail/dense.rs"]mod dense;
#[path="../native-pencil-tail/linear.rs"]mod linear;
#[path="../native-pencil-tail/tail.rs"]mod tail;
#[path="../native-pencil-tail/pencil.rs"]mod cheap;
#[path="../native-pencil-2lp/pencil.rs"]mod full;
use hec_native_ic::{counted,instance::pick_instance,rng::Rng};
fn main(){let old=include_str!("../native-pencil-2lp/CONTROL.txt");let mut calls=0;let mut failures=0;
 for line in include_str!("INSTANCES.tsv").lines().skip(1){counted::disable();let v:Vec<_>=line.split('\t').collect();let g:usize=v[0].parse().unwrap();let p:u64=v[1].parse().unwrap();let cc:u64=v[2].parse().unwrap();let ell:u64=v[3].parse().unwrap();let inst=pick_instance(p,g).unwrap();assert_eq!(inst.c,cc);assert_eq!(inst.ell,ell);assert_eq!(inst.curve.f.c[..inst.curve.f.n].iter().map(u64::to_string).collect::<Vec<_>>().join(","),v[4]);let mut rng=Rng::new(2026111800^p^((g as u64)<<32));
 for case in 0..2{let sm=if case==0{1}else{17};let d=inst.curve.mul(&inst.d1,sm);let k=1+rng.below(ell-1);let t=inst.curve.mul(&d,k);let prefix=format!("CASE g={g} p={p} c={cc} ell={ell} sm={sm} case={case} expected={k} report=");let oldline=old.lines().find(|l|l.starts_with(&prefix)).unwrap();let mut expected=oldline.strip_prefix(&prefix).unwrap().to_string();let start=expected.find("dense_audits: ").unwrap()+"dense_audits: ".len();let end=start+expected[start..].find(',').unwrap();expected.replace_range(start..end,"0");let mut prior=std::collections::BTreeMap::new();
 for rep in 0..2{let arms=if(case+rep)%2==0{[0,1]}else{[1,0]};for arm in arms{let name=if arm==0{"pencil_fullnorm"}else{"pencil_tail"};eprintln!("start g={g} p={p} case={case} arm={name} rep={rep}");counted::reset();let(answer,report)=if arm==0{let r=full::solve(&inst.curve,&d,&t,ell,512,false);assert_eq!(r.dense_audits,0);(r.k,format!("{r:?}"))}else{let r=cheap::solve(&inst.curve,&d,&t,ell,512,false);assert_eq!(r.dense_audits,0);(r.k,format!("{r:?}"))};let counts=counted::snapshot();counted::disable();assert_eq!(report,expected);if answer!=Some(k){failures+=1;}if let Some(answer)=answer{assert_eq!(answer,k);assert_eq!(inst.curve.mul(&d,answer),t);}if let Some(old)=prior.get(&arm){assert_eq!(old,&(answer,report.clone(),counts.clone()));}else{prior.insert(arm,(answer,report.clone(),counts.clone()));}
 println!("OUTCOME g={g} p={p} sm={sm} case={case} arm={name} rep={rep} report={report}");for(modulus,values)in counts{assert_eq!(values[8],2*values[7]+values[5]+values[6]);println!("COUNT g={g} p={p} source_multiple={sm} case={case} arm={name} rep={rep} modulus={modulus} vector={values:?}");}calls+=1;
 }} }}assert_eq!(calls,88);eprintln!("SUMMARY complete_calls={calls} fixtures=22 failures={failures} initial_mixed_term_models=11 matched_validation=true diagnostics_disabled=true full_reports_replay_exact_except_diagnostic_count=true repeated_vectors_exact=true prior_walk_fullbase_controls_unchanged=true no_wall_or_tenfold_claim=true");if failures>0{std::process::exit(2);}}
